package org.sleepwell.app;

import android.app.Activity;
import android.os.*;
import android.widget.*;
import java.util.UUID;

/** Explicit local access preference only; enabling never starts tracking or executes a request. */
public final class IncomingAutomationSettingsActivity extends Activity {
 private boolean enabled,resumed;private long revision;private String error="",request;private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);RecordUi.review(this);IncomingAutomation.Settings saved=IncomingAutomation.settings(this);enabled=saved.enabled;revision=saved.revision;error=saved.issue;if(b!=null){enabled=b.getBoolean("enabled",enabled);revision=b.getLong("revision",revision);error=b.getString("error",error);request=b.getString("request");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}
 private void render(){boolean busy=request!=null;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Incoming tracking requests",this::finish);Design.space(body,18);Switch allow=Design.toggle(body,"Allow reviewed requests","Off by default · foreground confirmation every time",enabled,on->enabled=on);allow.setEnabled(!busy);Design.space(body,16);Design.text(body,"Other apps can ask to start, pause, resume or stop tracking. They cannot directly control the service or dismiss alarms.",15,400,Design.INK);Design.space(body,12);Design.text(body,"START opens your normal tracking setup. Sensor choices, microphone access and its final Start button remain yours. Pause, resume and stop only apply to the recording you review.",14,400,Design.MUTED);Design.space(body,12);Design.text(body,"The phone must be unlocked. A request expires after two minutes. Access does not grant unattended, remote or vendor-compatible control.",14,400,Design.MUTED);Design.space(body,16);
  Design.item(body,"info","Version 1 request format","SleepWell's own Intent contract",()->SleepPicker.message(this,"Request format",IncomingAutomation.ACTION+"\n\nPackage: "+getPackageName()+"\nComponent: "+IncomingAutomationActivity.class.getName()+"\n\nExactly three extras:\nversion: integer 1\ncommand: START, PAUSE, RESUME or STOP\nrequest_id: new canonical UUID string\n\nLaunch the standard Activity with no data, nested intents or URI grants. A non-Activity caller may use NEW_TASK. To receive results, launch for result.\n\nResult extras: version, command, request_id, status. START returns staged; applied means the requested state was actually observed. Pending/interrupted never means a completed operation. Requests are not vendor action aliases."));
  Design.item(body,"info","Repeat and failure behavior","Prepared request IDs are never replayed",()->SleepPicker.message(this,"Request receipts","A private journal retains prepared IDs so repeat taps or a process interruption cannot blindly run the same request twice. Check tracking after pending or interrupted results; send a fresh UUID only after reviewing the current state.\n\nPermission denial, a locked phone, a changed recording, an active alarm or cleanup failure can reject the request. Turning this access off invalidates queued, unaccepted commands; an already accepted operation is not undone."));
  LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,13,500,Design.BROWN);if(busy)Design.text(footer,"Saving access…",13,400,Design.MUTED);Design.button(footer,"Save request access",true,()->{request=UUID.randomUUID().toString();error="";render();observe();}).setEnabled(!busy&&revision>=0);Design.button(footer,"Cancel",false,this::finish).setEnabled(!busy);
 }
 private void observe(){if(!resumed||request==null)return;String token=request;long expected=revision;boolean chosen=enabled;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{IncomingAutomation.saveSettings(app,chosen,expected,token);return null;});if(!operation.done){main.removeCallbacks(poll);main.postDelayed(poll,100);return;}PlanOperations.forget(token);request=null;if(operation.error!=null){error=operation.error;render();}else finish();}
 private final Runnable poll=this::observe;
 @Override protected void onResume(){super.onResume();resumed=true;observe();}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}@Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putBoolean("enabled",enabled);b.putLong("revision",revision);b.putString("error",error);b.putString("request",request);}@Override protected void onDestroy(){main.removeCallbacks(poll);super.onDestroy();}@Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}